function(container, apiUrl, tables) {
  const municipalitySelect = container.querySelector('#municipality-select');
  const newMunicipalityBtn = container.querySelector('#new-municipality-btn');
  const analyzeBtn = container.querySelector('#analyze-btn');
  const analysisResults = container.querySelector('#analysis-results');
  const modal = container.querySelector('#new-municipality-modal');
  const modalSaveBtn = container.querySelector('#modal-save-btn');
  const modalCancelBtn = container.querySelector('#modal-cancel-btn');
  const generateReportBtn = container.querySelector('#generate-report-btn');
  const exportCsvBtn = container.querySelector('#export-csv-btn');

  let currentMunicipality = null;
  let analysisData = null;

  // Load municipalities
  async function loadMunicipalities() {
    const rows = await window.aivicApi.list(0);
    if (rows && rows.length > 0) {
      rows.forEach(row => {
        const opt = document.createElement('option');
        opt.value = row.id;
        opt.textContent = row['自治体名'] || row.name || 'Unknown';
        municipalitySelect.appendChild(opt);
      });
    }
  }

  // Modal handlers
  newMunicipalityBtn.addEventListener('click', () => {
    modal.style.display = 'flex';
  });

  modalCancelBtn.addEventListener('click', () => {
    modal.style.display = 'none';
  });

  modal.addEventListener('click', (e) => {
    if (e.target === modal) modal.style.display = 'none';
  });

  modalSaveBtn.addEventListener('click', async () => {
    const newMun = {
      '自治体名': container.querySelector('#modal-name').value,
      '都道府県': container.querySelector('#modal-prefecture').value,
      '自治体コード': container.querySelector('#modal-code').value,
      '担当部門': container.querySelector('#modal-department').value,
      '担当者名': container.querySelector('#modal-contact').value,
      '連絡先メール': container.querySelector('#modal-email').value,
      '導入ステータス': '検討中'
    };
    const saved = await window.aivicApi.save(0, newMun);
    if (saved) {
      const opt = document.createElement('option');
      opt.value = saved.id;
      opt.textContent = saved['自治体名'];
      municipalitySelect.appendChild(opt);
      municipalitySelect.value = saved.id;
      modal.style.display = 'none';
      container.querySelectorAll('#modal-name, #modal-prefecture, #modal-code, #modal-department, #modal-contact, #modal-email').forEach(el => el.value = '');
    }
  });

  // Analyze button
  analyzeBtn.addEventListener('click', () => {
    const selectedId = municipalitySelect.value;
    if (!selectedId) {
      alert('自治体を選択してください');
      return;
    }

    const systemName = container.querySelector('#system-name').value;
    const templateSelect = container.querySelector('#template-select').value;
    if (!systemName || !templateSelect) {
      alert('必須項目を入力してください');
      return;
    }

    // Generate mock analysis data
    analysisData = {
      full: Math.floor(Math.random() * 20) + 5,
      partial: Math.floor(Math.random() * 15) + 5,
      none: Math.floor(Math.random() * 10) + 3,
      additional: Math.floor(Math.random() * 8) + 2,
      deviations: [
        { name: 'SSL/TLS対応', standard: '必須', current: '部分対応', impact: '高', priority: '高' },
        { name: '多要素認証', standard: '必須', current: '未対応', impact: '高', priority: '高' },
        { name: 'アクセス制御', standard: 'RBAC', current: 'ABAC', impact: '中', priority: '中' },
        { name: 'ログ保持期間', standard: '5年', current: '1年', impact: '中', priority: '中' },
        { name: 'バックアップ', standard: '日次', current: '週次', impact: '低', priority: '低' }
      ],
      riskScores: {
        total: Math.floor(Math.random() * 40) + 35,
        security: Math.floor(Math.random() * 5) + 3,
        operation: Math.floor(Math.random() * 5) + 2,
        technical: Math.floor(Math.random() * 5) + 3,
        organization: Math.floor(Math.random() * 5) + 2
      },
      priorities: {
        urgent: Math.floor(Math.random() * 5) + 2,
        recommended: Math.floor(Math.random() * 8) + 3,
        postimpl: Math.floor(Math.random() * 10) + 5,
        optional: Math.floor(Math.random() * 5) + 2
      }
    };

    // Update statistics
    container.querySelector('#stat-full').textContent = analysisData.full;
    container.querySelector('#stat-partial').textContent = analysisData.partial;
    container.querySelector('#stat-none').textContent = analysisData.none;
    container.querySelector('#stat-additional').textContent = analysisData.additional;

    // Draw pie chart
    const diffCanvas = container.querySelector('#diff-chart');
    const diffCtx = diffCanvas.getContext('2d');
    drawPieChart(diffCtx, [analysisData.full, analysisData.partial, analysisData.none, analysisData.additional], ['#4caf50', '#ff9800', '#f44336', '#2196f3']);

    // Update deviation table
    const tbody = container.querySelector('#deviation-tbody');
    tbody.innerHTML = '';
    analysisData.deviations.forEach(dev => {
      const tr = document.createElement('tr');
      tr.style.borderBottom = '1px solid var(--border)';
      tr.innerHTML = `
        <td style="padding: 8px; color: var(--text);">${dev.name}</td>
        <td style="padding: 8px; color: var(--text);">${dev.standard}</td>
        <td style="padding: 8px; color: var(--text);">${dev.current}</td>
        <td style="padding: 8px; color: var(--text);">${dev.impact}</td>
        <td style="padding: 8px; color: var(--text);">${dev.priority}</td>
      `;
      tbody.appendChild(tr);
    });

    // Update risk scores
    const riskLevel = analysisData.riskScores.total > 70 ? '極度のリスク' : analysisData.riskScores.total > 50 ? '高リスク' : analysisData.riskScores.total > 30 ? '中リスク' : '低リスク';
    container.querySelector('#risk-score').textContent = analysisData.riskScores.total;
    container.querySelector('#risk-level').textContent = riskLevel;
    container.querySelector('#risk-security').textContent = analysisData.riskScores.security;
    container.querySelector('#risk-operation').textContent = analysisData.riskScores.operation;
    container.querySelector('#risk-technical').textContent = analysisData.riskScores.technical;
    container.querySelector('#risk-organization').textContent = analysisData.riskScores.organization;

    // Draw radar chart
    const impactCanvas = container.querySelector('#impact-chart');
    const impactCtx = impactCanvas.getContext('2d');
    drawRadarChart(impactCtx, [analysisData.riskScores.security, analysisData.riskScores.operation, analysisData.riskScores.technical, analysisData.riskScores.organization, 4]);

    // Update priorities
    container.querySelector('#priority-urgent').textContent = analysisData.priorities.urgent;
    container.querySelector('#priority-recommended').textContent = analysisData.priorities.recommended;
    container.querySelector('#priority-postimpl').textContent = analysisData.priorities.postimpl;
    container.querySelector('#priority-optional').textContent = analysisData.priorities.optional;

    analysisResults.style.display = 'block';
  });

  // Report generation
  generateReportBtn.addEventListener('click', async () => {
    if (!analysisData) return;
    const report = {
      'レポート名': `差分分析レポート_${new Date().toISOString().split('T')[0]}`,
      'レポート種別': '差分分析',
      '対象期間開始日': new Date().toISOString(),
      '対象期間終了日': new Date().toISOString(),
      'ステータス': '完成',
      'レポート内容': JSON.stringify(analysisData)
    };
    const saved = await window.aivicApi.save(1, report);
    if (saved) alert('レポートを生成しました');
  });

  // CSV export
  exportCsvBtn.addEventListener('click', () => {
    if (!analysisData) return;
    let csv = '\uFEFF項目名,標準要件,現状,影響度,優先度\n';
    analysisData.deviations.forEach(dev => {
      csv += `"${dev.name}","${dev.standard}","${dev.current}","${dev.impact}","${dev.priority}"\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `差分分析_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // Chart drawing functions
  function drawPieChart(ctx, data, colors) {
    const total = data.reduce((a, b) => a + b, 0);
    let angle = 0;
    const centerX = ctx.canvas.width / 2;
    const centerY = ctx.canvas.height / 2;
    const radius = Math.min(centerX, centerY) - 10;

    data.forEach((value, i) => {
      const sliceAngle = (value / total) * Math.PI * 2;
      ctx.fillStyle = colors[i];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, angle, angle + sliceAngle);
      ctx.closePath();
      ctx.fill();
      angle += sliceAngle;
    });
  }

  function drawRadarChart(ctx, data) {
    const labels = ['セキュリティ', '運用', '技術', '組織', '総合'];
    const points = data.length;
    const centerX = ctx.canvas.width / 2;
    const centerY = ctx.canvas.height / 2;
    const radius = 80;
    const angleSlice = (Math.PI * 2) / points;

    ctx.strokeStyle = '#9ca3af';
    ctx.lineWidth = 1;
    for (let i = 0; i < 5; i++) {
      const r = (radius / 5) * (i + 1);
      ctx.beginPath();
      for (let j = 0; j < points; j++) {
        const x = centerX + r * Math.cos(angleSlice * j - Math.PI / 2);
        const y = centerY + r * Math.sin(angleSlice * j - Math.PI / 2);
        if (j === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.stroke();
    }

    ctx.strokeStyle = '#2c3e50';
    ctx.lineWidth = 2;
    ctx.fillStyle = 'rgba(44, 62, 80, 0.3)';
    ctx.beginPath();
    data.forEach((value, i) => {
      const r = (radius / 5) * (value / 5);
      const x = centerX + r * Math.cos(angleSlice * i - Math.PI / 2);
      const y = centerY + r * Math.sin(angleSlice * i - Math.PI / 2);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.closePath();
    ctx.stroke();
    ctx.fill();
  }

  loadMunicipalities();
}
